const http = require('http');
const { parse: parseUrl } = require('url');
const querystring = require('querystring');

const RESPONSE_REDIRECT_SYMBOL = Symbol.for('express.redirect');

function createApp() {
  const middlewares = [];
  const routes = { GET: [], POST: [] };

  function app(req, res) {
    if (!res[RESPONSE_REDIRECT_SYMBOL]) {
      res[RESPONSE_REDIRECT_SYMBOL] = true;
      res.redirect = function redirect(location) {
        res.statusCode = 302;
        res.setHeader('Location', location);
        res.end();
      };
    }

    req.body = req.body || {};
    const { pathname, query } = parseUrl(req.url, true);
    req.path = pathname;
    req.query = query || {};

    let idx = 0;
    const stack = [...middlewares, routeDispatcher];

    function next(err) {
      const layer = stack[idx++];
      if (!layer) {
        if (err) {
          res.statusCode = 500;
          res.end('Internal Server Error');
        } else if (!res.writableEnded) {
          res.statusCode = 404;
          res.end('Not Found');
        }
        return;
      }

      try {
        if (layer.length === 4) {
          if (err) {
            layer(err, req, res, next);
          } else {
            next();
          }
        } else if (err) {
          next(err);
        } else {
          layer(req, res, next);
        }
      } catch (error) {
        next(error);
      }
    }

    function routeDispatcher(request, response, nextMiddleware) {
      const method = request.method.toUpperCase();
      const candidates = routes[method] || [];
      for (const route of candidates) {
        if (route.path === pathname) {
          return route.handler(request, response);
        }
      }
      nextMiddleware();
    }

    next();
  }

  app.use = function use(middleware) {
    middlewares.push(middleware);
  };

  app.get = function get(path, handler) {
    routes.GET.push({ path, handler });
  };

  app.post = function post(path, handler) {
    routes.POST.push({ path, handler });
  };

  app.listen = function listen(port, callback) {
    const server = http.createServer(app);
    return server.listen(port, callback);
  };

  return app;
}

function urlencoded() {
  return function urlencodedMiddleware(req, res, next) {
    if (req.method.toUpperCase() !== 'POST') {
      next();
      return;
    }

    let data = '';
    req.on('data', (chunk) => {
      data += chunk;
    });
    req.on('end', () => {
      req.body = querystring.parse(data);
      next();
    });
    req.on('error', next);
  };
}

module.exports = createApp;
module.exports.urlencoded = function urlencodedFactory() {
  return urlencoded();
};
